"""lotus: tpch/Q28; common numeric v4; explicitly rewritten workload.
Source: original/tpch/plop/Q28.sql
Run via experiments.validation.faithful_runtime; model settings are external.
"""
SYSTEM = 'lotus'
QUERY_ID = 'tpch/Q28'
SOURCE = 'original/tpch/plop/Q28.sql'

RELATIONAL_SQL = "WITH joined AS (\n  SELECT\n    of.o_orderkey,\n    of.o_orderpriority,\n    of.o_totalprice,\n    of.o_comment,\n    of.o_orderdate,\n    of.o_custkey,\n    lf.l_partkey,\n    lf.l_suppkey,\n    lf.l_quantity,\n    lf.l_extendedprice,\n    lf.l_discount,\n    lf.l_shipmode\n  FROM (\n    SELECT\n      ob.o_orderkey,\n      ob.o_orderpriority,\n      ob.o_totalprice,\n      ob.o_comment,\n      ob.o_orderdate,\n      ob.o_custkey\n    FROM (\n      SELECT\n        o.o_orderkey,\n        o.o_orderpriority,\n        o.o_totalprice,\n        o.o_comment,\n        o.o_orderdate,\n        o.o_custkey\n      FROM orders AS o\n      WHERE\n        o.o_orderdate >= CAST('1995-01-01' AS DATE)\n        AND o.o_orderdate < CAST('1996-07-01' AS DATE)\n        AND o.o_totalprice BETWEEN 100000 AND 220000\n        AND o.o_orderstatus = 'O'\n        AND o.o_orderpriority IN ('1-URGENT', '2-HIGH')\n    ) AS ob\n    WHERE\n      SEMANTIC_FILTER(\n        'Does this order look operationally significant based on priority label, total price, and comment content?\nOrder Priority: {0}\nTotal Price: {1}\nComment: {2}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n        CAST(ob.o_orderpriority AS TEXT),\n        CAST(ob.o_totalprice AS TEXT),\n        CAST(ob.o_comment AS TEXT)\n      )\n  ) AS of\n  JOIN (\n    SELECT\n      l.l_orderkey,\n      l.l_partkey,\n      l.l_suppkey,\n      l.l_quantity,\n      l.l_extendedprice,\n      l.l_discount,\n      l.l_shipmode,\n      l.l_shipdate\n    FROM lineitem AS l\n    WHERE\n      l.l_shipdate >= CAST('1995-01-01' AS DATE)\n      AND l.l_shipdate < CAST('1996-07-01' AS DATE)\n      AND l.l_quantity BETWEEN 18 AND 26\n      AND l.l_discount BETWEEN 0.04 AND 0.07\n      AND l.l_shipmode IN ('AIR', 'REG AIR')\n  ) AS lf\n    ON lf.l_orderkey = of.o_orderkey\n)\nSELECT\n  *\nFROM joined AS j\nJOIN (\n  SELECT\n    c.c_custkey,\n    c.c_name,\n    c.c_address,\n    c.c_nationkey,\n    c.c_phone,\n    c.c_acctbal,\n    c.c_mktsegment,\n    c.c_comment\n  FROM customer AS c\n  JOIN (\n    SELECT DISTINCT\n      o_custkey\n    FROM joined\n    ORDER BY\n      o_custkey ASC\n    LIMIT 60\n  ) AS k\n    ON k.o_custkey = c.c_custkey\n  WHERE\n    SEMANTIC_FILTER(\n      'Does this customer look operationally strategic based on name style, market segment, and account balance?\nCustomer Name: {0}\nMarket Segment: {1}\nAccount Balance: {2}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n      CAST(c.c_name AS TEXT),\n      CAST(c.c_mktsegment AS TEXT),\n      CAST(c.c_acctbal AS TEXT)\n    )\n) AS cc\n  ON cc.c_custkey = j.o_custkey\n  AND SEMANTIC_JOIN(\n    'Could this customer account be strategically important for order fulfillment?\nOrder Priority: {0}\nOrder Total Price: {1}\nLineitem Ship Mode: {2}\nCustomer Name: {3}\nMarket Segment: {4}\nAccount Balance: {5}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n    CAST(j.o_orderpriority AS TEXT),\n    CAST(j.o_totalprice AS TEXT),\n    CAST(j.l_shipmode AS TEXT),\n    CAST(cc.c_name AS TEXT),\n    CAST(cc.c_mktsegment AS TEXT),\n    CAST(cc.c_acctbal AS TEXT)\n  );\n"

def run(tables, job, model=None):
    from experiments.validation.faithful_runtime import run_lotus_relational
    return run_lotus_relational(RELATIONAL_SQL, tables, job, model=model)

if __name__ == '__main__':
    from experiments.validation.faithful_runtime import query_main
    query_main(globals())
